export function test(): number {
  const holder: any = { last: 0 };
  const p: any = Promise.resolve(1);
  p.then = function (res: any) { res(11); };
  const alias: any = p;
  const outer: any = new Promise(function (res: any) { res(alias); });
  p.then = function (res: any) { res(22); };
  outer.then(function (val: any) { holder.last = (val === 11) ? 1 : (val === 22 ? 2 : 4); }, function () { holder.last = 3; });
  __drain_microtasks();
  return holder.last;
}

let gets = 0;
let calls = 0;
let wrongCalls = 0;
let value = 0;
let trace = 0;
let version = 0;
export function start(): number {
  const o: any = {};
  Object.defineProperty(o, "then", { get: function() {
    gets += 1;
    trace = trace * 10 + 1;
    if (version === 0) return function(res: any) {
      calls += 1;
      trace = trace * 10 + 2;
      res(42);
    };
    return function(res: any) {
      wrongCalls += 1;
      trace = trace * 10 + 8;
      res(99);
    };
  } });
  Promise.resolve(o).then(function(v: any) {
    value = v;
    trace = trace * 10 + 4;
  });
  trace = trace * 10 + 3;
  version = 1;
  return gets;
}
export function getGets(): number { return gets; }
export function getCalls(): number { return calls; }
export function getWrongCalls(): number { return wrongCalls; }
export function getValue(): number { return value; }
export function getTrace(): number { return trace; }
